public class J04 {
    static class Parent {
        String name = "parent";
        String who() { return "Parent"; }
    }
    static class Child extends Parent {
        String name = "child";
        String who() { return "Child"; }
    }

    public static void main(String[] args) {
        Parent value = new Child();
        System.out.println(value.name);
        System.out.println(value.who());
        System.out.println(((Child) value).name);
    }
}

public class J05 {
    static int attempt() {
        int value = 1;
        try {
            return value;
        } finally {
            value = 2;
        }
    }
    static StringBuilder build() {
        StringBuilder text = new StringBuilder("a");
        try {
            return text;
        } finally {
            text.append("b");
        }
    }

    public static void main(String[] args) {
        System.out.println(attempt());
        System.out.println(build());
    }
}

public class J06 {
    static void reassign(int[] values) { values = new int[]{9, 9}; }
    static void mutate(int[] values) { values[0] = 9; }
    static void grow(StringBuilder text) { text.append("!"); }
    static void replace(String text) { text = text + "!"; }

    public static void main(String[] args) {
        int[] numbers = {1, 2};
        reassign(numbers);
        System.out.println(numbers[0]);
        mutate(numbers);
        System.out.println(numbers[0]);
        StringBuilder builder = new StringBuilder("hi");
        grow(builder);
        System.out.println(builder);
        String text = "hi";
        replace(text);
        System.out.println(text);
    }
}

